-- Tabbit's numeric backend for LuaJIT 2.1.
--
-- The reader's decode logic is shared between LuaJIT and Lua 5.3+, but the two runtimes
-- spell low-level numeric work differently - 5.3's operator syntax does not even parse
-- under LuaJIT - so everything that differs lives behind this module's interface. The
-- 5.3+ twin is tcb_ops_53.lua; the two must answer identically for every input.
--
-- 64-bit values are FFI int64_t cdata here: arithmetic and comparisons work with the
-- ordinary operators, LuaJIT 2.1's bit.* operates on them at full width, and nothing is
-- lost the way a double would lose past 2^53. Two consequences the reader is built
-- around: cdata cannot serve as a table key by value (which is why int64 indexes are
-- sorted arrays, not hash tables), and tostring() appends an "LL" suffix (which is why
-- formatting goes through i64string).

local ffi = require("ffi")
local bit = require("bit")

local band, bor, bxor = bit.band, bit.bor, bit.bxor
local lshift, rshift, tobit = bit.lshift, bit.rshift, bit.tobit

local int64_t = ffi.typeof("int64_t")
local uint64_t = ffi.typeof("uint64_t")
local ONE = uint64_t(1)

-- One scratch union for every fixed-width load. Reading a field copies the value out,
-- so reusing the buffer aliases nothing.
local conv = ffi.new([[
  union {
    uint8_t bytes[8];
    int32_t i32;
    uint32_t u32;
    int64_t i64;
    float f32;
    double f64;
  }
]])

local function load_bytes(s, at, count)
  ffi.copy(conv.bytes, ffi.cast("const char *", s) + at, count)
end

local ops = {}

ops.name = "luajit"

-- A signed 32-bit integer, little endian, at 0-based offset `at`.
function ops.i32(s, at)
  load_bytes(s, at, 4)
  return conv.i32
end

function ops.u32(s, at)
  load_bytes(s, at, 4)
  return tonumber(conv.u32)
end

-- An int64 as boxed cdata.
function ops.i64(s, at)
  load_bytes(s, at, 8)
  return conv.i64
end

function ops.f32(s, at)
  load_bytes(s, at, 4)
  return conv.f32
end

function ops.f64(s, at)
  load_bytes(s, at, 8)
  return conv.f64
end

-- The zig-zag fold of a 64-bit varint, from its 7-bit pieces in stream order.
function ops.dezig64(pieces)
  local encoded = uint64_t(0)

  for i = #pieces, 1, -1 do
    encoded = bor(lshift(encoded, 7), pieces[i])
  end

  -- -(encoded & 1) is all ones when the low bit was set, which is the fold's mask.
  local mask = -band(encoded, ONE)

  return ffi.cast(int64_t, bxor(rshift(encoded, 1), mask))
end

-- A wrapping int32 sum, mirroring the writer's wrapping subtraction.
function ops.add32(a, b)
  return tobit(a + b)
end

-- A fresh bit-pack accumulator, and setting one bit of it.
ops.slot0 = uint64_t(0)

function ops.setbit(slot, at)
  return bor(slot, lshift(ONE, at))
end

-- Whether bit `i` of a byte value is set.
function ops.bittest(byte, i)
  return band(rshift(byte, i), 1) == 1
end

-- base + slot over 64 bits, wrapping, signed on the way out.
function ops.addbase64(base, slot)
  return ffi.cast(int64_t, ffi.cast(uint64_t, base) + slot)
end

-- The low 32 bits of a 64-bit value, sign extended, as a plain number.
function ops.to32(v)
  return tobit(tonumber(band(v, 0xFFFFFFFFULL)))
end

-- A number as the float subtype. A no-op here, where every number is a double.
function ops.tofloat(n)
  return n + 0.0
end

-- An int64 as decimal digits, without the cdata suffix tostring appends.
function ops.i64string(v)
  local s = tostring(v)
  return (s:gsub("[UL]+$", ""))
end

-- Decimal digits as an int64 cdata. Digit by digit rather than tonumber, whose result
-- here is a double and rounds past 2^53.
function ops.i64parse(s)
  local negative = s:sub(1, 1) == "-"
  local from = negative and 2 or 1
  local value = int64_t(0)

  for i = from, #s do
    local digit = s:byte(i) - 48

    if digit < 0 or digit > 9 then
      error("not a number: " .. s, 0)
    end

    value = value * 10 + digit
  end

  if negative then
    value = -value
  end

  return value
end

return ops
